class ValidationError extends Error {}

// createUser({ name, age }) returns { name, age } or throws a ValidationError.
// Rules:
//   name: a string that isn't empty after trimming.
//   age: a whole number from 0 to 150. It comes from a form, so it may be a number
//        or a numeric string like "42". The returned age is always a number.
function createUser(input) {
  if (input === null || typeof input !== 'object') {
    throw new ValidationError('input must be an object');
  }

  const { name, age } = input;

  if (typeof name !== 'string' || name.trim() === '') {
    throw new ValidationError('name must be a non-empty string');
  }

  let ageNumber;
  if (typeof age === 'number') {
    ageNumber = age;
  } else if (typeof age === 'string' && /^\s*\d+\s*$/.test(age)) {
    ageNumber = Number(age);
  } else {
    throw new ValidationError('age must be a whole number or a numeric string');
  }

  if (!Number.isInteger(ageNumber) || ageNumber < 0 || ageNumber > 150) {
    throw new ValidationError('age must be a whole number from 0 to 150');
  }

  return { name: name.trim(), age: ageNumber };
}

module.exports = { createUser, ValidationError };

